/// <summary>
/// Insert execution history
/// </summary>
/// <param name = "_definitionGroupExecution"><c>DMFDefinitionGroupExecution</c> record</param>
public void insertExecutionHistory(DMFDefinitionGroupExecution  _definitionGroupExecution)
{
    next insertExecutionHistory(_definitionGroupExecution);

    notes DMFerror;
    boolean isError = false;

    if (_definitionGroupExecution.StagingStatus == DMFBatchJobStatus::Error)
    {
        DMFerror = "@MET:DErr";
        isError = true;
    }
    else if (_definitionGroupExecution.TargetStatus == DMFBatchJobStatus::Error)
    {
        str errorMessage = "@DMF:StagingToTargetImportFailed";
        DMFerror = "@MET:METError" + ' ' + strFmt("@DMF:EntityImportError", _definitionGroupExecution.Entity, errorMessage);
        isError = true;
    }

    if (isError || _definitionGroupExecution.TargetErrorCount > 0)
    {
        //Based on the flags the primary key detail will be added in the error
        // CB718 VM Task - 162235 Replace logging with new format start
        METTelemetryDMFLogging metTelemetryDMFLogging = METTelemetryDMFLogging::construct(_definitionGroupExecution,DMFerror);

        if(DMFEntity::find(_definitionGroupExecution.Entity).METIncludeErrorLogging && SysIntParameters::find().METEntityLogging)
        {
            DMFerror += METSysGlobalTelemetry::getPrimaryKeyDetails(_definitionGroupExecution,metTelemetryDMFLogging);
        }
        metTelemetryDMFLogging.error = DMFerror;
        metTelemetryDMFLogging.processEvent(METApplicationInsightsEventNames::DMFError);//eventName);
        // CB718 VM Task - end
    }

}
